-- Register the 137 public objects that had no schema_ownership row (found by scripts/supabase-liveness.mjs).
--
-- Owner is inferred, and every evidence line says so: the only repo whose code names it (migrations and
-- generated types excluded, since grantscope/supabase/migrations holds every repo's DDL); "shared" when
-- several do; act for private ACT data (xero_, ghl_, email_ ...) whatever reads it; else a name prefix;
-- else unknown. Each line also names the migration that created the object where one was found, and
-- its liveness verdict. Correct any row with a later UPDATE; nothing reads schema_ownership to decide access.
--
-- Apply: scripts/db-apply.sh supabase/migrations/20260926100000_register_unregistered_objects.sql (Tier 3)

BEGIN;
ON CONFLICT (object) DO NOTHING;
COMMIT;
